const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DATA_DIR = path.resolve(__dirname, '../../seed-data/json');

function createQ(track, idNum, topic, difficulty, question, options, correctIndex, explanation, tags = []) {
  return {
    id: `Q-${track.toUpperCase()}-${String(idNum).padStart(3, '0')}`,
    track,
    topic,
    difficulty,
    type: 'MCQ',
    question,
    options,
    correctIndex,
    explanation,
    tags,
    isSample: true,
  };
}

